btn-gradient-slide:
.fx-btn-gradient-slide {
  position: relative;
  border: none;
  cursor: pointer;
  padding: 14px 36px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.3px;
  color: #fff;
  border-radius: 12px;
  background: linear-gradient(120deg, #10b981, #f43f5e, #10b981);
  background-size: 200% 100%;
  background-position: 0% 50%;
  box-shadow: 0 10px 25px -10px rgba(16, 185, 129, 0.6);
  transition: background-position 0.6s ease, transform 0.25s ease, box-shadow 0.25s ease;
}
.fx-btn-gradient-slide:hover {
  background-position: 100% 50%;
  transform: translateY(-2px);
  box-shadow: 0 18px 35px -12px rgba(244, 63, 94, 0.7);
}
.fx-btn-gradient-slide:active { transform: translateY(0); }

btn-neon-glow:
.fx-btn-neon-glow {
  position: relative;
  padding: 14px 34px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #2dd4bf;
  background: transparent;
  border: 2px solid #2dd4bf;
  border-radius: 8px;
  cursor: pointer;
  text-shadow: 0 0 8px rgba(45, 212, 191, 0.8);
  box-shadow:
    0 0 5px rgba(45, 212, 191, 0.6),
    inset 0 0 5px rgba(45, 212, 191, 0.3);
  animation: fx-neon-pulse 1.8s ease-in-out infinite;
}
.fx-btn-neon-glow:hover {
  color: #0a0a0a;
  background: #2dd4bf;
  text-shadow: none;
}
@keyframes fx-neon-pulse {
  0%, 100% { box-shadow: 0 0 5px rgba(45,212,191,0.6), 0 0 12px rgba(45,212,191,0.4), inset 0 0 5px rgba(45,212,191,0.3); }
  50%      { box-shadow: 0 0 12px rgba(45,212,191,0.9), 0 0 28px rgba(45,212,191,0.6), inset 0 0 10px rgba(45,212,191,0.5); }
}

btn-3d-press:
.fx-btn-3d-press {
  position: relative;
  border: none;
  cursor: pointer;
  padding: 14px 32px;
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  background: #10b981;
  border-radius: 10px;
  box-shadow: 0 6px 0 #047857, 0 8px 14px rgba(0,0,0,0.25);
  transition: transform 0.08s ease, box-shadow 0.08s ease;
}
.fx-btn-3d-press:hover { background: #34d399; }
.fx-btn-3d-press:active {
  transform: translateY(6px);
  box-shadow: 0 0 0 #047857, 0 2px 6px rgba(0,0,0,0.25);
}

btn-liquid-fill:
.fx-btn-liquid-fill {
  position: relative;
  overflow: hidden;
  padding: 14px 34px;
  font-size: 15px;
  font-weight: 600;
  color: #f43f5e;
  background: transparent;
  border: 2px solid #f43f5e;
  border-radius: 999px;
  cursor: pointer;
  isolation: isolate;
  transition: color 0.35s ease;
}
.fx-btn-liquid-fill::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: #f43f5e;
  border-radius: 999px;
  transform: translateY(101%);
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.fx-btn-liquid-fill:hover { color: #fff; }
.fx-btn-liquid-fill:hover::before { transform: translateY(0); }

btn-border-trace:
.fx-btn-border-trace {
  position: relative;
  padding: 14px 34px;
  font-size: 15px;
  font-weight: 600;
  color: #fbbf24;
  background: rgba(251, 191, 36, 0.06);
  border: none;
  border-radius: 10px;
  cursor: pointer;
  overflow: hidden;
}
.fx-btn-border-trace::before,
.fx-btn-border-trace::after {
  content: "";
  position: absolute;
  background: #fbbf24;
}
.fx-btn-border-trace::before {
  top: 0; left: 0;
  width: 100%; height: 2px;
  transform: translateX(-100%);
  transition: transform 0.35s ease;
}
.fx-btn-border-trace::after {
  bottom: 0; right: 0;
  width: 100%; height: 2px;
  transform: translateX(100%);
  transition: transform 0.35s ease 0.2s;
}
.fx-btn-border-trace:hover::before,
.fx-btn-border-trace:hover::after { transform: translateX(0); }
.fx-btn-border-trace:hover { box-shadow: 0 0 18px rgba(251, 191, 36, 0.35); }

btn-shine-sweep:
.fx-btn-shine-sweep {
  position: relative;
  overflow: hidden;
  padding: 14px 36px;
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(135deg, #14b8a6, #34d399);
  border: none;
  border-radius: 10px;
  cursor: pointer;
  box-shadow: 0 8px 20px -8px rgba(52, 211, 153, 0.6);
}
.fx-btn-shine-sweep::before {
  content: "";
  position: absolute;
  top: 0; left: -120%;
  width: 60%; height: 100%;
  background: linear-gradient(120deg, transparent, rgba(255,255,255,0.55), transparent);
  transform: skewX(-25deg);
}
.fx-btn-shine-sweep:hover::before {
  animation: fx-shine 0.9s ease;
}
@keyframes fx-shine {
  100% { left: 120%; }
}

btn-skew-slide:
.fx-btn-skew-slide {
  padding: 14px 34px;
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  background: #111827;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transform: skew(-12deg);
  transition: background 0.25s ease, transform 0.25s ease;
}
.fx-btn-skew-slide:hover {
  background: #f97316;
  transform: skew(-12deg) translateX(4px);
}

loader-spinner:
.fx-loader-spinner {
  position: relative;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  border: 3px solid transparent;
  border-top-color: #10b981;
  border-right-color: #10b981;
  animation: fx-spin 1s linear infinite;
}
.fx-loader-spinner span {
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  border: 3px solid transparent;
  border-bottom-color: #f43f5e;
  border-left-color: #f43f5e;
  animation: fx-spin 0.7s linear reverse infinite;
}
@keyframes fx-spin { to { transform: rotate(360deg); } }

loader-dots:
.fx-loader-dots { display: inline-flex; gap: 8px; }
.fx-loader-dots span {
  width: 14px; height: 14px;
  border-radius: 50%;
  background: #10b981;
  animation: fx-dots 1.2s ease-in-out infinite;
}
.fx-loader-dots span:nth-child(2) { animation-delay: 0.2s; background: #14b8a6; }
.fx-loader-dots span:nth-child(3) { animation-delay: 0.4s; background: #0d9488; }
@keyframes fx-dots {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.6; }
  30%           { transform: translateY(-12px); opacity: 1; }
}

loader-pulse-ring:
.fx-loader-pulse-ring {
  position: relative;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #f43f5e;
}
.fx-loader-pulse-ring::before,
.fx-loader-pulse-ring::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid #f43f5e;
  animation: fx-pulse-ring 1.6s ease-out infinite;
}
.fx-loader-pulse-ring::after { animation-delay: 0.8s; }
@keyframes fx-pulse-ring {
  0%   { transform: scale(1);   opacity: 0.8; }
  100% { transform: scale(3);   opacity: 0; }
}

loader-bars:
.fx-loader-bars { display: inline-flex; gap: 5px; align-items: flex-end; height: 44px; }
.fx-loader-bars span {
  width: 7px;
  height: 100%;
  background: linear-gradient(180deg, #f59e0b, #ef4444);
  border-radius: 4px;
  animation: fx-bars 1s ease-in-out infinite;
}
.fx-loader-bars span:nth-child(2) { animation-delay: 0.15s; }
.fx-loader-bars span:nth-child(3) { animation-delay: 0.3s; }
.fx-loader-bars span:nth-child(4) { animation-delay: 0.45s; }
.fx-loader-bars span:nth-child(5) { animation-delay: 0.6s; }
@keyframes fx-bars {
  0%, 100% { transform: scaleY(0.3); }
  50%      { transform: scaleY(1); }
}

loader-orbit:
.fx-loader-orbit {
  position: relative;
  width: 64px;
  height: 64px;
}
.fx-loader-orbit::before {
  content: "";
  position: absolute;
  inset: 24px;
  border-radius: 50%;
  background: #fde047;
  box-shadow: 0 0 14px rgba(253, 224, 71, 0.8);
}
.fx-loader-orbit span {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px dashed rgba(52, 211, 153, 0.4);
  animation: fx-orbit 2.4s linear infinite;
}
.fx-loader-orbit span::after {
  content: "";
  position: absolute;
  top: -6px;
  left: 50%;
  width: 12px; height: 12px;
  margin-left: -6px;
  border-radius: 50%;
  background: #34d399;
}
.fx-loader-orbit span:nth-child(2) {
  inset: 12px;
  animation-duration: 1.6s;
  animation-direction: reverse;
  border-color: rgba(45, 212, 191, 0.4);
}
.fx-loader-orbit span:nth-child(2)::after { background: #2dd4bf; }
@keyframes fx-orbit { to { transform: rotate(360deg); } }

loader-cube:
.fx-loader-cube {
  width: 44px; height: 44px;
  transform: rotateZ(45deg);
  position: relative;
}
.fx-loader-cube span {
  display: block;
  position: absolute;
  width: 20px; height: 20px;
  background: #2dd4bf;
  animation: fx-cube-fold 2.4s infinite linear;
}
.fx-loader-cube span:nth-child(1) { top: 0; left: 0; }
.fx-loader-cube span:nth-child(2) { top: 0; right: 0; animation-delay: 0.6s; background: #10b981; }
.fx-loader-cube span:nth-child(3) { bottom: 0; left: 0; animation-delay: 1.2s; background: #f43f5e; }
.fx-loader-cube span:nth-child(4) { bottom: 0; right: 0; animation-delay: 1.8s; background: #f59e0b; }
@keyframes fx-cube-fold {
  0%, 10%    { transform: perspective(120px) rotateX(-180deg); opacity: 0; }
  25%, 75%   { transform: perspective(120px) rotateX(0deg);    opacity: 1; }
  90%, 100%  { transform: perspective(120px) rotateY(180deg);  opacity: 0; }
}

card-glass:
.fx-stage-aurora {
  background:
    radial-gradient(circle at 20% 20%, rgba(16,185,129,0.7), transparent 45%),
    radial-gradient(circle at 80% 30%, rgba(244,63,94,0.7), transparent 45%),
    radial-gradient(circle at 50% 80%, rgba(45,212,191,0.6), transparent 50%),
    #0f1a17;
}
.fx-card-glass {
  position: relative;
  width: 260px;
  padding: 24px;
  border-radius: 18px;
  color: #fff;
  background: rgba(255,255,255,0.08);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid rgba(255,255,255,0.18);
  box-shadow: 0 12px 40px rgba(0,0,0,0.35);
}
.fx-card-glass h3 { font-size: 20px; font-weight: 700; margin: 8px 0 6px; }
.fx-card-glass p { font-size: 13px; opacity: 0.85; margin: 0 0 16px; line-height: 1.5; }
.fx-card-glass-badge {
  display: inline-block;
  font-size: 10px; font-weight: 700; letter-spacing: 1px;
  padding: 4px 10px;
  color: #052e2b;
  background: linear-gradient(135deg, #fde047, #f59e0b);
  border-radius: 999px;
}
.fx-card-glass-btn {
  border: none;
  cursor: pointer;
  padding: 10px 18px;
  font-weight: 600;
  color: #052e2b;
  background: rgba(255,255,255,0.9);
  border-radius: 10px;
  transition: transform 0.2s ease, background 0.2s ease;
}
.fx-card-glass-btn:hover { transform: translateY(-2px); background: #fff; }

card-spotlight:
.fx-card-spotlight {
  position: relative;
  width: 260px;
  padding: 26px;
  border-radius: 16px;
  color: #e5e7eb;
  background: #0f172a;
  border: 1px solid rgba(255,255,255,0.08);
  overflow: hidden;
  cursor: pointer;
  transition: border-color 0.3s ease, transform 0.3s ease;
  --mx: 50%; --my: 50%;
}
.fx-card-spotlight::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(180px circle at var(--mx) var(--my), rgba(52,211,153,0.25), transparent 60%);
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}
.fx-card-spotlight:hover { border-color: rgba(52,211,153,0.5); transform: translateY(-3px); }
.fx-card-spotlight:hover::before { opacity: 1; }
.fx-card-spotlight h3 { font-size: 18px; font-weight: 700; margin: 0 0 8px; color: #fff; position: relative; }
.fx-card-spotlight p { font-size: 13px; opacity: 0.7; margin: 0; position: relative; }
.fx-card-spotlight-cta {
  position: absolute;
  right: 22px; bottom: 22px;
  font-size: 20px;
  color: #34d399;
  transition: transform 0.3s ease;
}
.fx-card-spotlight:hover .fx-card-spotlight-cta { transform: translateX(4px); }

card-flip:
.fx-card-flip {
  width: 220px; height: 140px;
  perspective: 1000px;
  cursor: pointer;
}
.fx-card-flip-face {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: 14px;
  backface-visibility: hidden;
  transition: transform 0.7s cubic-bezier(0.4, 0.2, 0.2, 1);
}
.fx-card-flip-front {
  background: linear-gradient(135deg, #10b981, #f43f5e);
  color: #fff;
}
.fx-card-flip-back {
  background: linear-gradient(135deg, #10b981, #0d9488);
  color: #fff;
  transform: rotateY(180deg);
}
.fx-card-flip:hover .fx-card-flip-front { transform: rotateY(-180deg); }
.fx-card-flip:hover .fx-card-flip-back  { transform: rotateY(0); }
.fx-card-flip-icon { font-size: 32px; }
.fx-card-flip-face p { margin: 0; font-weight: 600; font-size: 14px; }

card-neon-border:
.fx-card-neon-border {
  position: relative;
  width: 240px;
  padding: 2px;
  border-radius: 16px;
  background: conic-gradient(from 0deg, #10b981, #f43f5e, #f59e0b, #2dd4bf, #10b981);
}
.fx-card-neon-border::before {
  content: "";
  position: absolute;
  inset: -100%;
  background: conic-gradient(from 0deg, transparent, #10b981, #f43f5e, #f59e0b, #2dd4bf, transparent);
  animation: fx-neon-spin 4s linear infinite;
  z-index: -1;
}
.fx-card-neon-inner {
  position: relative;
  padding: 24px;
  border-radius: 14px;
  background: #0f1a17;
  color: #fff;
  text-align: left;
}
.fx-card-neon-inner h3 { margin: 0 0 6px; font-size: 18px; font-weight: 700; }
.fx-card-neon-inner p { margin: 0; font-size: 13px; opacity: 0.7; }
@keyframes fx-neon-spin { to { transform: rotate(360deg); } }

text-gradient:
.fx-stage-dark { background: #0f1a17; }
.fx-text-gradient {
  margin: 0;
  font-size: 40px;
  font-weight: 800;
  letter-spacing: -0.5px;
  background: linear-gradient(90deg, #10b981, #f43f5e, #f59e0b, #2dd4bf, #10b981);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: fx-grad-flow 6s linear infinite;
}
@keyframes fx-grad-flow {
  to { background-position: 300% 50%; }
}

text-glitch:
.fx-text-glitch {
  position: relative;
  margin: 0;
  font-size: 44px;
  font-weight: 800;
  color: #fff;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 4px;
}
.fx-text-glitch::before,
.fx-text-glitch::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  background: #0f1a17;
  overflow: hidden;
}
.fx-text-glitch::before {
  color: #2dd4bf;
  animation: fx-glitch-1 2s infinite linear alternate-reverse;
  clip-path: polygon(0 0, 100% 0, 100% 33%, 0 33%);
}
.fx-text-glitch::after {
  color: #f43f5e;
  animation: fx-glitch-2 1.4s infinite linear alternate-reverse;
  clip-path: polygon(0 67%, 100% 67%, 100% 100%, 0 100%);
}
@keyframes fx-glitch-1 {
  0%   { transform: translate(0); }
  20%  { transform: translate(-3px, 1px); }
  40%  { transform: translate(3px, -1px); }
  60%  { transform: translate(-2px, -1px); }
  80%  { transform: translate(2px, 1px); }
  100% { transform: translate(0); }
}
@keyframes fx-glitch-2 {
  0%, 100% { transform: translate(0); }
  50%      { transform: translate(4px, -2px); }
}

text-neon:
.fx-text-neon {
  margin: 0;
  font-size: 56px;
  font-weight: 800;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 6px;
  text-shadow:
    0 0 6px #fff,
    0 0 14px #fff,
    0 0 28px #f43f5e,
    0 0 60px #f43f5e,
    0 0 90px #f43f5e;
  animation: fx-flicker 3.2s infinite alternate;
}
@keyframes fx-flicker {
  0%, 19%, 21%, 23%, 25%, 54%, 56%, 100% {
    text-shadow:
      0 0 6px #fff, 0 0 14px #fff,
      0 0 28px #f43f5e, 0 0 60px #f43f5e, 0 0 90px #f43f5e;
    opacity: 1;
  }
  20%, 24%, 55% {
    text-shadow: none;
    opacity: 0.5;
  }
}

text-shimmer:
.fx-text-shimmer {
  margin: 0;
  font-size: 36px;
  font-weight: 800;
  letter-spacing: -0.5px;
  background: linear-gradient(90deg, #475569 0%, #475569 40%, #fff 50%, #475569 60%, #475569 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: fx-shimmer-text 2.2s linear infinite;
}
@keyframes fx-shimmer-text {
  to { background-position: -200% 50%; }
}

text-3d:
.fx-text-3d {
  margin: 0;
  font-size: 56px;
  font-weight: 900;
  letter-spacing: 2px;
  color: #fff;
  text-shadow:
    1px 1px 0 #cbd5e1,
    2px 2px 0 #cbd5e1,
    3px 3px 0 #cbd5e1,
    4px 4px 0 #94a3b8,
    5px 5px 0 #94a3b8,
    6px 6px 0 #64748b,
    7px 7px 0 #64748b,
    8px 8px 0 #475569,
    9px 9px 0 #334155,
    10px 10px 18px rgba(0,0,0,0.35);
}

bg-mesh:
.fx-bg-mesh {
  width: 100%; height: 100%;
  background:
    radial-gradient(at 20% 20%, #10b981 0px, transparent 50%),
    radial-gradient(at 80% 10%, #f43f5e 0px, transparent 50%),
    radial-gradient(at 60% 80%, #2dd4bf 0px, transparent 50%),
    radial-gradient(at 10% 90%, #f59e0b 0px, transparent 50%),
    #0f1a17;
  background-size: 200% 200%;
  animation: fx-mesh-shift 12s ease-in-out infinite;
}
@keyframes fx-mesh-shift {
  0%, 100% { background-position: 0% 0%, 100% 0%, 50% 100%, 0% 100%; }
  50%      { background-position: 30% 50%, 70% 30%, 30% 70%, 70% 70%; }
}

bg-grid:
.fx-bg-grid {
  width: 100%; height: 100%;
  background:
    linear-gradient(rgba(45,212,191,0.18) 1px, transparent 1px) 0 0 / 40px 40px,
    linear-gradient(90deg, rgba(45,212,191,0.18) 1px, transparent 1px) 0 0 / 40px 40px,
    radial-gradient(ellipse at center, #0f1a17 0%, #000 100%);
  animation: fx-grid-pan 8s linear infinite;
}
@keyframes fx-grid-pan {
  to { background-position: 40px 40px, 40px 40px, 0 0; }
}

bg-aurora:
.fx-bg-aurora {
  width: 100%; height: 100%;
  background: #050816;
  position: relative;
  overflow: hidden;
}
.fx-bg-aurora::before,
.fx-bg-aurora::after {
  content: "";
  position: absolute;
  inset: -50%;
  background: conic-gradient(from 0deg, transparent, #10b981, transparent 30%, #2dd4bf, transparent 60%, #34d399, transparent);
  filter: blur(60px);
  opacity: 0.5;
  animation: fx-aurora-spin 14s linear infinite;
}
.fx-bg-aurora::after {
  animation-duration: 22s;
  animation-direction: reverse;
  opacity: 0.35;
}
@keyframes fx-aurora-spin { to { transform: rotate(360deg); } }

bg-orbs:
.fx-bg-orbs {
  width: 100%; height: 100%;
  background: #0f1a17;
  position: relative;
  overflow: hidden;
}
.fx-bg-orbs span {
  position: absolute;
  bottom: -80px;
  width: 120px; height: 120px;
  border-radius: 50%;
  filter: blur(8px);
  opacity: 0.7;
  animation: fx-orb-rise 10s ease-in infinite;
}
.fx-bg-orbs span:nth-child(1) { left: 10%; background: #10b981; animation-delay: 0s; }
.fx-bg-orbs span:nth-child(2) { left: 35%; background: #f43f5e; animation-delay: 2.5s; width: 80px; height: 80px; }
.fx-bg-orbs span:nth-child(3) { left: 60%; background: #2dd4bf; animation-delay: 5s; }
.fx-bg-orbs span:nth-child(4) { left: 85%; background: #f59e0b; animation-delay: 7s; width: 60px; height: 60px; }
@keyframes fx-orb-rise {
  0%   { transform: translateY(0) scale(1); opacity: 0; }
  10%  { opacity: 0.7; }
  90%  { opacity: 0.5; }
  100% { transform: translateY(-400px) scale(0.5); opacity: 0; }
}

hover-underline:
.fx-hover-underline {
  position: relative;
  font-size: 18px;
  font-weight: 600;
  color: #1f2937;
  text-decoration: none;
  cursor: pointer;
  padding-bottom: 4px;
}
.fx-hover-underline::after {
  content: "";
  position: absolute;
