    .fx-loader-circle-fade span:nth-child(6)::after { animation-delay: 0.60s; }
    .fx-loader-circle-fade span:nth-child(7)::after { animation-delay: 0.72s; }
    .fx-loader-circle-fade span:nth-child(8)::after { animation-delay: 0.84s; }
