    .fx-bg-confetti span:nth-child(4) { left: 44%; background: #0d9488; animation-duration: 4.5s; animation-delay: 1.5s; transform: rotate(30deg); }
    .fx-bg-confetti span:nth-child(5) { left: 57%; background: #10b981; animation-duration: 3.2s; animation-delay: 0.3s; }
    .fx-bg-confetti span:nth-child(6) { left: 70%; background: #f43f5e; animation-duration: 3.8s; animation-delay: 0.8s; transform: rotate(60deg); }
