    /* Cycles through 4 words */
    @keyframes fx-typing-cycle {
      0%   { width: 0ch; }
      /* "design" */
      4%   { width: 0ch; }
      20%  { width: 6ch; }
      25%  { width: 6ch; }
      /* erase */
      29%  { width: 0ch; }
      /* "code" */
      33%  { width: 0ch; }
      45%  { width: 4ch; }
      50%  { width: 4ch; }
      54%  { width: 0ch; }
      /* "ship" */
      58%  { width: 0ch; }
      70%  { width: 4ch; }
      75%  { width: 4ch; }
